/**
 * Lift a page's promise line out of the markdown body into `description`
 * frontmatter.
 *
 * The convention: an H1 is followed by a one-paragraph blockquote stating what
 * the page is for. That blockquote IS the description -- it has one definition
 * site (the source doc, which also ships in the npm tarball and reads correctly
 * as plain markdown), and the frontmatter derives from it. A page without one
 * simply renders no description.
 *
 * Returns `[description, remainingBody]`.
 */
function liftPromise(body) {
  const match = body.match(/^((?:>.*\n)+)\n/);
  if (!match) return ['', body];
  const description = match[1]
    .split('\n')
    .filter(Boolean)
    .map((line) => line.replace(/^>\s?/, ''))
    .join(' ')
    .trim();
  return [description, body.slice(match[0].length)];
}

// Mintlify callout components -> Blume block directives. The source docs author
// callouts as block-level tags on their own lines (`<Note>` ... `</Note>`), so a
// plain tag swap is safe -- the content in between is untouched.
const CALLOUTS = { Note: 'note', Warning: 'warning', Tip: 'tip', Info: 'info' };

function rewriteCallouts(text) {
  let out = text;
  for (const [tag, kind] of Object.entries(CALLOUTS)) {
    out = out
      .replace(new RegExp(`<${tag}>`, 'g'), `:::${kind}`)
      .replace(new RegExp(`</${tag}>`, 'g'), ':::');
  }
  return out;
}

/**
 * Escape MDX-hostile chars in a prose segment (never inside code). Lowercase
 * angle-brackets (`<model>`, `<your_db>`) are placeholders and get escaped so
 * MDX doesn't read them as tags; `{`/`}` are escaped so MDX doesn't read them as
 * expressions. Callouts have already been rewritten to `:::` directives, so no
 * PascalCase component tags survive into this step.
 */
function escapeProse(text) {
  return text
    .replace(/<(?![A-Z]|\/[A-Z])/g, '&lt;') // escape `<` unless it opens/closes a component
    .replace(/\{/g, '&#123;')
    .replace(/\}/g, '&#125;');
}

/**
 * Split markdown into fenced-code blocks (passed through verbatim) and
 * everything else (prose, where inline-code spans are also protected).
 */
function transform(md, slug) {
  // 1. Pull out fenced code blocks so their contents are never escaped.
  const fences = [];
  let body = md.replace(/```[\s\S]*?```/g, (m) => {
    fences.push(m);
    return ` FENCE${fences.length - 1} `;
  });

  // 2. Drop the leading H1 -- the frontmatter title becomes the page heading --
  // then lift the promise line that follows it into `description`.
  body = body.replace(/^\s*#\s+.*\n+/, '');
  const [description, rest] = liftPromise(body);
  body = rest;

  // 2b. Link rewriting for the site.
  const GH = 'https://github.com/Abloatai/ablo/blob/main';
  body = body
    // Repo-root files that aren't site pages -> GitHub; the changelog -> its page.
    .replace(
      /\]\((?:\.\.?\/)*(README|AGENTS)\.md(#[A-Za-z0-9_-]+)?\)/g,
      (_, name, anchor = '') => `](${GH}/${name}.md${anchor})`,
    )
    .replace(/\]\((?:\.\.?\/)*CHANGELOG\.md\)/g, '](/changelog)')
    // Some source links carry a `/docs` base path; the site serves at root.
    .replace(/\]\(\/docs\//g, '](/')
    // Relative `.md` links -> site routes (extensionless, root-relative):
    // `[x](./foo.md#a)` / `[x](foo.md)` -> `[x](/foo#a)`.
    .replace(
      /\]\((?:\.\/|\.\.\/)?([A-Za-z0-9_/-]+)\.md(#[A-Za-z0-9_-]+)?\)/g,
      (_, path, anchor = '') => `](/${path}${anchor})`,
    );

  // 2c. Mintlify callout components -> Blume `:::` directives.
  body = rewriteCallouts(body);

  // 3. Escape prose, protecting inline-code spans (which may span newlines).
  body = body
    .split(/(`[^`]*`)/)
    .map((seg) => (seg.startsWith('`') && seg.endsWith('`') ? seg : escapeProse(seg)))
    .join('');

  // 4. Restore fenced code blocks.
  body = body.replace(/ FENCE(\d+) /g, (_, i) => fences[Number(i)]);

  const title = TITLES[slug];
  const descLine = description ? `description: ${JSON.stringify(description)}\n` : '';
  const iconLine = ICONS[slug] ? `sidebar:\n  icon: ${ICONS[slug]}\n` : '';
  // Blume composes every document title as "<page> - <site title>", and the
  // site title is the landing page's own name ("Ablo Docs"). An empty SEO title
  // makes the landing page's <title> and og:title the bare site title instead of
  // "Ablo Docs - Ablo Docs"; the heading and the sidebar still use `title`.
  const seoLine = slug === 'index' ? `seo:\n  title: ""\n` : '';
  const frontmatter = `---\ntitle: ${JSON.stringify(title)}\n${descLine}${iconLine}${seoLine}---\n\n`;
  return frontmatter + body.replace(/^\n+/, '').replace(/\s+$/, '') + '\n';
}

/** Hard check: no residual MDX-hostile chars outside code/frontmatter. */
function validate(mdx, label) {
  const fences = [];
  let body = mdx.replace(/```[\s\S]*?```/g, (m) => {
    fences.push(m);
    return '';
  });
  body = body.replace(/^---\n[\s\S]*?\n---\n/, ''); // strip frontmatter
  body = body.replace(/\{\/\*[\s\S]*?\*\/\}/g, ''); // strip MDX comments (banner)
  const prose = body.replace(/`[^`]*`/g, '');
  // A lowercase `<tag` is a placeholder MDX would choke on; PascalCase `<Tag`
  // is an intentional component and is allowed.
  const badLt = prose.match(/<[a-z]/g);
  const badBrace = prose.match(/[{}]/g);
  const problems = [];
  if (badLt) problems.push(`${badLt.length} bare lowercase '<' (would parse as JSX)`);
  if (badBrace) problems.push(`${badBrace.length} bare '{' or '}' (would parse as JSX expression)`);
  if (problems.length) throw new Error(`${label}: ${problems.join('; ')}`);
}

/** Convert a markdown body to an MDX-safe body (fence- and inline-code-aware). */
function escapeMdxBody(md) {
  const fences = [];
  let body = md.replace(/```[\s\S]*?```/g, (m) => {
    fences.push(m);
    return ` FENCE${fences.length - 1} `;
  });
  body = body
    .split(/(`[^`]*`)/)
    .map((seg) => (seg.startsWith('`') && seg.endsWith('`') ? seg : escapeProse(seg)))
    .join('');
  return body.replace(/ FENCE(\d+) /g, (_, i) => fences[Number(i)]);
}

/** An ISO 8601 instant normalised to UTC, which is the shape the registry
 *  already answers (`2026-08-22T07:54:44.867Z`). Applied to the git source so a
 *  page stamped from a commit sorts against registry-stamped neighbours instead
 *  of comparing as a different kind of value.
 *
 *  The FULL timestamp matters, not just the day. Blume's changelog index sorts
 *  on this value alone, so day-granularity dates make same-day releases compare
 *  equal; the sort is stable, the tie keeps collection order (ascending), and
 *  four entries render oldest-first inside an otherwise newest-first list.
 *  0.42.0 through 0.45.0 all shipped on 2026-07-29, which is exactly that case.
 *  Seconds break the tie, and the rendered date is unchanged either way.
 *
 *  Null for a value that is not a date, which drops the caller to the next
 *  source rather than writing `Invalid Date` into frontmatter. */
function toUtcInstant(value) {
  const at = new Date(value);
  return Number.isNaN(at.getTime()) ? null : at.toISOString();
}

/** When each version was actually published, straight from the registry.
 *
 *  The best answer for a page that does not carry a date yet. A release is
 *  routinely prepared, reverted and re-prepared, so several
 *  `release(ablo): X.Y.Z` commits exist per version with different dates and no
 *  reliable way to tell which one shipped: 0.46.0 carried three across two days
 *  and the commit heuristic picked a date npm disagrees with.
 *
 *  It cannot be the last word, because it is the one input that does not exist
 *  when the page is written. The registry learns a version minutes AFTER
 *  `release.sh prepare` has generated its page and committed it, so ranking the
 *  registry above the stamped date meant every release pushed a commit that a
 *  fresh `check:docs-site` called stale on a tree nobody had edited. See
 *  {@link existingChangelogDates}.
 *
 *  `version -> ISO 8601`; empty when the registry is unreachable, which drops
 *  us to the git heuristic below rather than failing an offline docs build. */
function npmPublishTimes() {
  const map = {};
  try {
    const raw = execFileSync('npm', ['view', '@abloatai/ablo', 'time', '--json'], {
      encoding: 'utf8',
      maxBuffer: 8 * 1024 * 1024,
      stdio: ['ignore', 'pipe', 'ignore'],
    });
    for (const [version, when] of Object.entries(JSON.parse(raw))) {
      if (/^\d+\.\d+\.\d+$/.test(version)) map[version] = when;
    }
  } catch {
    return map; // offline or npm missing -> fall back to the commit heuristic
  }
  return map;
}

/** Release dates from the `release(ablo): X.Y.Z` commits (CHANGELOG.md carries
 *  no dates). `version -> ISO 8601`; absent when no such commit.
 *
 *  Last in precedence, but it is what STAMPS a page the first time: at
 *  `release.sh prepare` the release commit is the only source that exists, the
 *  page having no date and the registry having never heard of the version. The
 *  ambiguity {@link npmPublishTimes} describes does not reach that case, since
 *  the commit was written seconds earlier by the run now reading it. The AUTHOR
 *  date is what we read, because it survives the `--amend` that folds the
 *  regenerated page into the release commit; a committer date would shift under
 *  the fold and answer differently on the next build. */
function releaseDates() {
  const map = {};
  let log;
  try {
    log = execFileSync('git', ['log', '--all', '--pretty=%aI%x09%s'], {
      cwd: repoRoot,
      encoding: 'utf8',
      maxBuffer: 32 * 1024 * 1024,
    });
  } catch {
    return map; // no git context -> entries fall back to filesystem order
  }
  for (const line of log.split('\n')) {
    const tab = line.indexOf('\t');
    if (tab < 0) continue;
    const m = line.slice(tab + 1).match(/release\(ablo\):\s*(\d+\.\d+\.\d+)/);
    if (!m || map[m[1]]) continue;
    const at = toUtcInstant(line.slice(0, tab));
    if (at) map[m[1]] = at;
  }
  return map;
}

/** The version a `## X.Y.Z` section opens with, as a `[major, minor]` pair. */
function versionParts(part) {
  const [major, minor] = part.slice(0, part.indexOf('\n')).trim().split('.').map(Number);
  return [major ?? 0, minor ?? 0];
}

/**
 * The changelog category shown next to each entry's date, derived from the step
 * this version took over the one below it.
 *
 * It used to read the section body for Changesets' `### Minor Changes` heading.
 * That heading is never there to find: `finalize-release-notes.mjs` replaces the
 * generated body with the hand-written note before this generator runs, and the
 * note's headings are sentences. So both branches were unreachable and all
 * eighteen pages published as `Fixes`, feature releases included.
 *
 * The version headings are the surviving evidence of the bump, and this file
 * already walks them, so the category is read from the same data rather than
 * from prose that has to remember to say it.
 */
function changelogCategory(part, previousPart) {
  const [major, minor] = versionParts(part);
  // The oldest entry has nothing below it; measure it from the empty version.
  const [previousMajor, previousMinor] = previousPart ? versionParts(previousPart) : [0, 0];
  if (major !== previousMajor) return 'Breaking';
  return minor !== previousMinor ? 'Features' : 'Fixes';
}

/** How many of the newest changelog entries stay in the agent-facing files
 *  (`llms.txt`/`llms-full.txt`, search). Recent entries carry current-truth
 *  migration guidance an agent needs; older ones announce APIs that have since
 *  changed shape or left the SDK, and an agent reading the full history can
 *  meet a feature announcement before its removal note. Older entries stay on
 *  the site (`/changelog` renders every page) — `noindex` only keeps them out
 *  of the agent files and search. */
const CHANGELOG_AGENT_WINDOW = 12;

/** The `date:` a changelog page already carries, `version -> value`.
 *
 *  The HIGHEST-precedence source, and the whole reason this generator is
 *  stable: a release date does not change, so once a page carries one, that IS
 *  the date. No later source may revise it, and the value is passed through
 *  unnormalised because normalising it would be a revision.
 *
 *  Ranking it top is what makes a page a function of inputs that all exist at
 *  the moment it is written. The two sources below answer at moments the page
 *  cannot wait for: the registry only after the publish, the commit log only
 *  once `release(ablo): x.y.z` has landed. While either outranked the stamped
 *  value, the page committed by `prepare` was GUARANTEED to disagree with the
 *  same page regenerated an hour later. That is not drift worth catching; it is
 *  the generator disagreeing with itself.
 *
 *  Sitting above the commit log, this already kept a build that cannot reach
 *  npm from rewriting dates it did not author. Sitting above the registry too,
 *  it extends the same guarantee to the machine that CAN. */
function existingChangelogDates() {
  const map = {};
  let files;
  try {
    files = readdirSync(CHANGELOG_DIR);
  } catch {
    return map; // first build, or the folder was cleared
  }
  for (const file of files) {
    const version = file.replace(/\.mdx$/, '');
    if (!/^\d+\.\d+\.\d+$/.test(version)) continue;
    const date = readFileSync(resolve(CHANGELOG_DIR, file), 'utf8').match(/^date: (.+)$/m);
    if (date) map[version] = date[1];
  }
  return map;
}

/** One Blume changelog page per `## X.Y.Z` section of CHANGELOG.md. Each page is
 *  `type: changelog`, and Blume assembles them into the `/changelog` timeline. */
function buildChangelogPages() {
  const raw = readFileSync(resolve(packageRoot, 'CHANGELOG.md'), 'utf8');
  // Stamp once, never revise. A date already on the page wins outright; a page
  // without one takes the registry's instant, and failing that the release
  // commit's. Later keys win, so this reads bottom-of-precedence first.
  const dates = {
    ...releaseDates(),
    ...npmPublishTimes(),
    ...existingChangelogDates(),
  };
  return raw
    .split(/^## (?=\d+\.\d+\.\d+)/m)
    .slice(1)
    .map((part, index, all) => {
      const nl = part.indexOf('\n');
      const version = part.slice(0, nl).trim().replace(/\s*\(.*\)$/, '');
      // CHANGELOG.md uses the internal package name; the public site uses the
      // published one (the doc-drift lint enforces this for the prose docs).
      const sectionBody = escapeMdxBody(part.slice(nl + 1).trim())
        .replace(/@ablo\/ablo/g, '@abloatai/ablo')
        .trim();
      // Newest-first, so the preceding release is the next entry along.
      const category = changelogCategory(part, all[index + 1]);
      const dateLine = dates[version] ? `date: ${dates[version]}\n` : '';
      // CHANGELOG.md is newest-first, so the index is the entry's age.
      const noindexLine = index >= CHANGELOG_AGENT_WINDOW ? 'noindex: true\n' : '';
      const frontmatter =
        `---\n` +
        `title: "v${version}"\n` +
        `type: changelog\n` +
        dateLine +
        noindexLine +
        `changelog:\n  version: "${version}"\n  category: "${category}"\n` +
        `---\n\n`;
      return { version, content: `${frontmatter}${sectionBody}\n` };
    });
}

/**
 * Every site route a link may target: the pages generated here, the pages the
 * site tree carries under their own pipelines (`errors`, `examples/`, `mcp/`),
 * and the two routes mounted by `blume.config.ts`.
 */
function siteRoutes() {
  const routes = new Set(Object.keys(TITLES).map((slug) => `/${slug}`));
  routes.add('/').add('/changelog').add('/api-reference');
  const walk = (dir, prefix) => {
    for (const entry of readdirSync(dir, { withFileTypes: true })) {
      if (entry.isDirectory()) walk(resolve(dir, entry.name), `${prefix}${entry.name}/`);
      else if (/\.mdx?$/.test(entry.name)) routes.add(`${prefix}${entry.name.replace(/\.mdx?$/, '')}`);
    }
  };
  walk(OUT, '/');
  return routes;
}

/**
 * A component's `href` is a JSX attribute, so the markdown link rewriter above
 * never sees it -- `<Card href="/coordination">` survives a page rename as a
 * silent 404. Pin every one to a route that exists.
 */
function validateHrefs(mdx, label, routes) {
  const bad = [...mdx.matchAll(/href="(\/[^"#]*)(?:#[^"]*)?"/g)]
    .map(([, href]) => href)
    .filter((href) => !routes.has(href.replace(/\/$/, '') || '/'));
  if (bad.length) throw new Error(`${label}: href targets no site page: ${bad.join(', ')}`);
}

/**
 * The product line has ONE definition site: the promise line under the H1 of
 * `docs/index.md`. The site config derives it from the generated frontmatter;
 * `llms.txt` opens with the same line as a sentence, and the README carries it
 * twice, as the banner under the logo and as the paragraph that opens the page.
 * None of them may drift.
 *
 * The README was the copy this check did not cover, and it is the copy npm and
 * GitHub show first. It went on calling Ablo "the transaction layer for AI
 * agents" long after the docs had settled on collaboration infrastructure,
 * because nothing compared the two. Adding a carrier to the list below is how a
 * new copy of the line earns the right to exist.
 */
function validateTagline(promise) {
  if (!promise) throw new Error('docs/index.md has no promise line under its H1');

  // The README wraps its prose at the column, so the sentence it carries has a
  // line break in the middle. Comparing raw text fails on the wrap and teaches
  // the next reader to unwrap one paragraph to appease the build.
  const flatten = (text) => text.replace(/\s+/g, ' ');

  const sentence = `Ablo is ${promise[0].toLowerCase()}${promise.slice(1)}`;
  // The banner states the category on its own: the promise up to the colon,
  // which is the clause naming what Ablo IS rather than what it does.
  const banner = `${promise.split(':')[0].trim()}.`;

  /** Every file that restates the line, and the form it restates it in. */
  const carriers = [
    { file: 'llms.txt', form: 'sentence', expected: sentence },
    { file: 'README.md', form: 'opening paragraph', expected: sentence },
    { file: 'README.md', form: 'banner', expected: banner },
  ];

  for (const { file, form, expected } of carriers) {
    const text = flatten(readFileSync(resolve(packageRoot, file), 'utf8'));
    if (text.includes(flatten(expected))) continue;
    throw new Error(
      `${file} does not carry the landing page's promise line as its ${form}.\n` +
        `       expected: ${expected}\n` +
        `       Edit docs/index.md if the line itself should change; ${file} follows it.`,
    );
  }
}

/**
 * Whether this commit can move the projection out of step.
 *
 * Anything under the source docs or the generated tree can, and so can the
 * generator itself and the two files that restate the landing page's promise
 * line. A commit touching none of them leaves the check nothing to say, and a
 * hook that runs anyway is a hook people learn to pass with `--no-verify`.
 */
function stagedTouchesTheProjection() {
  const staged = execFileSync('git', ['diff', '--cached', '--name-only'], {
    cwd: repoRoot,
    encoding: 'utf8',
  })
    .split('\n')
    .filter(Boolean);
  const watched = [
    'packages/ablo/docs/',
    'docs/ablo/docs/',
    'packages/ablo/scripts/build-blume-docs.mjs',
    'packages/ablo/README.md',
    'packages/ablo/llms.txt',
  ];
  return staged.some((path) => watched.some((prefix) => path.startsWith(prefix)));
}

const check = process.argv.includes('--check');
const stagedOnly = process.argv.includes('--staged');
if (stagedOnly && !check) {
  throw new Error('--staged is a mode of --check; pass both');
}
if (stagedOnly && !stagedTouchesTheProjection()) process.exit(0);

const routes = siteRoutes();
const stale = [];
let landingPromise = '';
let count = 0;

for (const slug of Object.keys(TITLES)) {
  const srcPath = resolve(SRC, `${slug}.md`);
  let md;
  try {
    md = readFileSync(srcPath, 'utf8');
  } catch {
    throw new Error(`Missing source doc: ${srcPath} (listed in TITLES)`);
  }
  const out = transform(md, slug);
  validate(out, `${slug}.mdx`);
  validateHrefs(out, `${slug}.mdx`, routes);
  if (slug === 'index') {
    const described = out.match(/^description: (".*")$/m);
    landingPromise = described ? JSON.parse(described[1]) : '';
  }
  const outPath = resolve(OUT, `${slug}.mdx`);
  if (check) {
    let current = '';
    try {
      current = readFileSync(outPath, 'utf8');
    } catch {
      /* missing -> stale */
    }
    if (current !== out) stale.push(slug);
  } else {
    // Nested slugs (`examples/…`) need their folder before the first write.
    mkdirSync(resolve(outPath, '..'), { recursive: true });
    writeFileSync(outPath, out);
  }
  count++;
}

validateTagline(landingPromise);

// Changelog: one `type: changelog` page per release, assembled into the timeline.
// Skipped in `--staged` mode, where its registry lookup would make the verdict
// depend on the network; see the preamble.
const changelogPages = stagedOnly ? [] : buildChangelogPages();
if (!check) {
  // Rebuild the folder from scratch so removed releases don't linger.
  rmSync(CHANGELOG_DIR, { recursive: true, force: true });
  mkdirSync(CHANGELOG_DIR, { recursive: true });
}
for (const { version, content } of changelogPages) {
  validate(content, `changelog/${version}.mdx`);
  const pagePath = resolve(CHANGELOG_DIR, `${version}.mdx`);
  if (check) {
    let current = '';
    try {
      current = readFileSync(pagePath, 'utf8');
    } catch {
      /* missing -> stale */
    }
    if (current !== content) stale.push(`changelog/${version}`);
  } else {
    writeFileSync(pagePath, content);
  }
}

if (check) {
  if (stale.length) {
    console.error(
      `[docs] Site pages are stale vs the package docs: ${stale.join(', ')}\n` +
        `       Run \`npm run build:docs\` and commit docs/ablo/**.`,
    );
    process.exit(1);
  }
  console.log(
    stagedOnly
      ? `[docs] ${count} pages in sync with the package docs (changelog not checked — run \`npm run check:docs-site\`)`
      : `[docs] ${count} pages + ${changelogPages.length} changelog entries in sync with the package docs`,
  );
} else {
  console.log(
    `[docs] generated ${count} pages + ${changelogPages.length} changelog entries -> docs/ablo/`,
  );
}
